 v_structure jsonb;
 v_item jsonb;
 v_oid oid;
begin
 perform pg_advisory_xact_lock(hashtextextended('rtw:reconcile-production-provenance:20261101',0));
 if (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prokind='f' and (n.nspname='private' or p.proname like 'rtw_%' or p.proname like 'flappy_%')) <> jsonb_array_length(v_expected)
 then raise exception 'Function inventory changed; stop reconciliation'; end if;
 for v_item in select value from jsonb_array_elements(v_expected) loop
   v_oid := to_regprocedure(v_item->>'signature');
   if v_oid is null or md5(regexp_replace(pg_get_functiondef(v_oid),'[[:space:]]+',' ','g')) is distinct from v_item->>'hash'
     or (select coalesce(proacl::text,'') from pg_proc where oid=v_oid) is distinct from v_item->>'acl'
   then raise exception 'Function definition or grants changed: %',v_item->>'signature'; end if;
 end loop;
 with catalog as (select jsonb_build_object(
'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'acl',p.proacl::text) order by n.nspname,p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prokind='f' and (n.nspname='private' or p.proname like 'rtw_%' or p.proname like 'flappy_%')),
'indexes',(select jsonb_agg(to_jsonb(i) order by schemaname,indexname) from pg_indexes i where schemaname in ('public','private')),
'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname in ('public','private')),
'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','private')),
'columns',(select jsonb_agg(to_jsonb(c) order by table_schema,table_name,ordinal_position) from information_schema.columns c where table_schema in ('public','private')),
'grants',(select jsonb_agg(to_jsonb(g) order by table_schema,table_name,grantee,privilege_type) from information_schema.role_table_grants g where table_schema in ('public','private')),
'column_grants',(select jsonb_agg(to_jsonb(g) order by table_schema,table_name,column_name,grantee,privilege_type) from information_schema.role_column_grants g where table_schema in ('public','private')),
'constraints',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',co.conname,'definition',pg_get_constraintdef(co.oid)) order by n.nspname,c.relname,co.conname) from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')),
'rls',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'rls',c.relrowsecurity,'force',c.relforcerowsecurity) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind='r')
) as snapshot) select jsonb_build_object('indexes',md5((snapshot->'indexes')::text),'policies',md5((snapshot->'policies')::text),'triggers',md5((snapshot->'triggers')::text),'columns',md5((snapshot->'columns')::text),'grants',md5((snapshot->'grants')::text),'column_grants',md5((snapshot->'column_grants')::text),'constraints',md5((snapshot->'constraints')::text),'rls',md5((snapshot->'rls')::text)) into v_structure from catalog;
 if v_structure is distinct from '{"rls":"5c2aa3e7c8c258d9f8c1e70442a11e42","grants":"d1c9c7cf204861b5d1d6a9edffd44e28","columns":"04f21401482f4f78b42620b44bbff6cc","indexes":"dbbd797051154d2b855d414c19307631","policies":"afbef46a6559d65c469d77433aa2da53","triggers":"7cfe086f2a897de83c3476fccb0d8226","constraints":"4057628d22e40d8339f1771c3427cdd4","column_grants":"d74f2a0d7efc73e3b381d613245da473"}'::jsonb
 then raise exception 'Application structure changed; stop reconciliation'; end if;
 if not exists(select 1 from private.flappy_turnstile_control where singleton and enabled)
 then raise exception 'Turnstile control changed'; end if;
 if position('when 1 then 500 when 2 then 300 when 3 then 200' in pg_get_functiondef('public.flappy_admin_allocate_prize(uuid,date,uuid,text)'::regprocedure))=0
 or position('v_eligible_cents < 2000' in pg_get_functiondef('public.rtw_begin_balance_payout_request(uuid)'::regprocedure))=0
 then raise exception 'Canonical financial invariant changed'; end if;
end;
$reconcile$;

